 const classes=(r.classes??[]).map((x:any)=>x.class?.name).filter(Boolean).join(', '),status=inspection?.status;
 return <><tr className="clickable-row" onClick={()=>setOpen(true)}><td data-label="№"><strong>{r.participantNumber}</strong></td><td data-label="Участник"><strong>{[r.participant?.lastName,r.participant?.firstName].filter(Boolean).join(' ')}</strong>{r.participant?.team&&<small className="table-sub">{r.participant.team}</small>}</td><td data-label="Автомобиль"><strong>{displayCarName(r.car)}</strong>{r.car?.registrationNumber&&<small className="table-sub">{r.car.registrationNumber}</small>}</td><td data-label="Классы">{classes||'—'}</td><td data-label="Инспекция">{status==='PASSED'?<span className="badge good"><Check size={11}/>Прошёл</span>:status==='FAILED'?<span className="badge bad"><X size={11}/>Не прошёл</span>:<span className="badge">Ожидает</span>}</td><td data-label="Действие" className="row-actions" onClick={e=>e.stopPropagation()}>{canEdit?<button className="secondary-button compact" onClick={()=>setOpen(true)}><Info size={14}/>Открыть</button>:<button className="secondary-button compact" onClick={()=>setOpen(true)}>Подробнее</button>}</td></tr>
 {open&&<InspectionDetailModal registration={r} user={user} readOnly={readOnly} busy={busy} error={error} notes={notes} noteOpen={noteOpen} setNotes={setNotes} setNoteOpen={setNoteOpen} onClose={()=>{if(!busy){setOpen(false);setError('')}}} onSave={save}/>}
 </>;
