   {error&&<div className="form-error"><AlertTriangle size={16}/><span>{error}</span></div>}
   {canEdit&&<div className="detail-actions"><button className="primary-button" disabled={busy} onClick={()=>void onSave('PASSED')}><Check size={16}/>{busy?'Сохраняем…':'Подтвердить: прошёл'}</button><button className="danger-button" disabled={busy} onClick={()=>setNoteOpen(true)}><X size={16}/>Не прошёл</button></div>}
